const hdr=$('#hd'),tp=$('#top'),pb=$('#pb'),pn=$('#pn'),ov=$('#ov'),hm=$('#ham');
const sc=()=>{const y=scrollY;hdr.classList.toggle('s',y>40);tp.classList.toggle('on',y>700);pb.style.transform='scaleX('+(y/Math.max(1,document.documentElement.scrollHeight-innerHeight))+')'};addEventListener('scroll',sc,{passive:true});sc();
tp.onclick=()=>scrollTo({top:0});const tg=o=>{pn.classList.toggle('open',o);ov.classList.toggle('open',o);document.body.classList.toggle('lock',o);hm.setAttribute('aria-expanded',o)};
hm.onclick=()=>tg(true);$('#cl').onclick=ov.onclick=()=>tg(false);$$('#pn a').forEach(a=>a.addEventListener('click',()=>tg(false)));addEventListener('keydown',e=>e.key==='Escape'&&tg(false));addEventListener('resize',()=>innerWidth>=1100&&tg(false));
document.addEventListener('click',e=>{const s=e.target.closest('[data-s]');if(s){e.preventDefault();const t=$('#vids');t&&t.scrollIntoView({behavior:'smooth'});return}const b=e.target.closest('.vid[data-yt]');if(!b)return;const d=document.createElement('div');d.className='vid vfr';d.innerHTML='<iframe src="https://www.youtube-nocookie.com/embed/'+b.dataset.yt+'?autoplay=1&rel=0" title="'+b.getAttribute('aria-label').replace('Play video: ','')+'" allow="accelerometer;autoplay;clipboard-write;encrypted-media;gyroscope;picture-in-picture;web-share" allowfullscreen loading="lazy"></iframe>';b.replaceWith(d)});

